package net.fabricmc.fabric.api.client.event.lifecycle.v1;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.client.Minecraft;

/** Fabric API: the client finished starting / is stopping (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class ClientLifecycleEvents {
    private ClientLifecycleEvents() {}

    public static final Event<ClientStarted> CLIENT_STARTED = EventFactory.createArrayBacked(ClientStarted.class, ls -> client -> { for (ClientStarted l : ls) l.onClientStarted(client); });
    public static final Event<ClientStopping> CLIENT_STOPPING = EventFactory.createArrayBacked(ClientStopping.class, ls -> client -> { for (ClientStopping l : ls) l.onClientStopping(client); });

    @FunctionalInterface public interface ClientStarted { void onClientStarted(Minecraft client); }
    @FunctionalInterface public interface ClientStopping { void onClientStopping(Minecraft client); }
}
